-- Тема 07: варианты ответов выровнены по длине и форме (64 исправлений в 23 вопросах), ключи не меняются.
-- Источник: scripts/questions/069_option_length_topic07.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Какую страницу выбирает алгоритм вытеснения из буферного кеша?', 'Случайную', 'Случайную из занятых буферов', 'Выбор не случайный.', NULL),
        ('option', 'Какую страницу выбирает алгоритм вытеснения из буферного кеша?', 'Ту, что в последнее время использовалась реже других', 'Ту, к которой реже всего обращались', 'Алгоритм по счётчику обращений приближённо выбирает редко используемые страницы.', 'Алгоритм по счётчику обращений приближённо выбирает страницы, которые в последнее время использовались реже других.'),
        ('option', 'Какую страницу выбирает алгоритм вытеснения из буферного кеша?', 'Самую большую', 'Ту, что дольше всех не менялась', 'Все страницы одного размера.', 'Изменения страницы для выбора не важны: учитывается частота обращений.'),
        ('option', 'В чём главное правило журнала предзаписи (WAL)?', 'Данные пишутся на диск раньше журнала', 'Изменённые данные попадают на диск раньше журнала', 'Наоборот: сначала журнал, потом данные.', NULL),
        ('option', 'В чём главное правило журнала предзаписи (WAL)?', 'Журнал пишется только при COMMIT', 'Журнал пишется на диск при каждом COMMIT и не раньше', 'Журнал пишется постоянно, а синхронная фиксация ждёт его сброса на диск.', NULL),
        ('option', 'В чём главное правило журнала предзаписи (WAL)?', 'Журнал хранится только в памяти', 'Журнал хранится в памяти до остановки сервера', 'Журнал записывается на диск, иначе по нему нельзя восстановиться.', NULL),
        ('option', 'В чём главное правило журнала предзаписи (WAL)?', 'Журнальная запись попадает на диск раньше изменённых ею данных', 'Журнал попадает на диск раньше изменённых данных', 'Тогда после сбоя изменения можно восстановить по журналу.', 'Журнальная запись попадает на диск раньше изменённых ею данных, поэтому после сбоя изменения можно восстановить по журналу.'),
        ('option', 'Какие таблицы не защищены журналом предзаписи?', 'Таблицы системного каталога', 'Таблицы системного каталога pg_catalog', 'Системный каталог журналируется.', NULL),
        ('option', 'Какие таблицы не защищены журналом предзаписи?', 'Секционированные таблицы', 'Секционированные таблицы и их секции', 'Данные лежат в секциях, обычные секции журналируются.', NULL),
        ('option', 'Какие таблицы не защищены журналом предзаписи?', 'Таблицы с индексами', 'Таблицы, у которых есть индексы', 'Обычные таблицы и их индексы журналируются; у UNLOGGED-таблиц индексы тоже не журналируются.', NULL),
        ('option', 'Что делает контрольная точка?', 'Удаляет мёртвые версии строк', 'Удаляет мёртвые версии строк из таблиц', 'Это задача очистки.', NULL),
        ('option', 'Что делает контрольная точка?', 'Переключает сервер на реплику', 'Копирует заполненные сегменты журнала в архив', 'Переключение на реплику — отдельная процедура.', 'В архив сегменты копирует процесс archiver.'),
        ('option', 'Что делает контрольная точка?', 'Сбрасывает на диск все грязные буферы и ограничивает объём журнала для восстановления', 'Сбрасывает на диск все грязные буферы', 'После неё восстановление начинается с этой точки.', 'Сбрасывает на диск все буферы, грязные на начало контрольной точки, и ограничивает объём журнала для восстановления: после неё восстановление начинается с этой точки.'),
        ('option', 'Чем процесс bgwriter отличается от checkpointer?', 'Записывает журнал предзаписи', 'Записывает журнал предзаписи на диск вместо walwriter', 'Журнал пишет walwriter.', NULL),
        ('option', 'Чем процесс bgwriter отличается от checkpointer?', 'Записывает все грязные буферы сразу', 'Записывает все грязные буферы кеша за один проход', 'Checkpointer записывает буферы, грязные на начало контрольной точки, обычно растягивая запись во времени.', NULL),
        ('option', 'Чем процесс bgwriter отличается от checkpointer?', 'Заранее читает страницы в кеш', 'Заранее читает в кеш страницы, нужные запросам', 'Упреждающего чтения в кеш bgwriter не делает.', NULL),
        ('option', 'Чем процесс bgwriter отличается от checkpointer?', 'Записывает только часть грязных буферов — те, что скоро будут вытеснены', 'Пишет грязные буферы, которые скоро будут вытеснены', 'Чтобы у вытесняемых буферов уже была записанная копия.', 'bgwriter пишет только часть грязных буферов — те, что скоро будут вытеснены, чтобы у них уже была записанная копия.'),
        ('option', 'Что защищает журнал предзаписи?', 'Нежурналируемые таблицы', 'Нежурналируемые таблицы (UNLOGGED)', 'Нет. Данные UNLOGGED-таблиц не защищаются WAL: после сбоя они очищаются, а определение таблицы сохраняется.', NULL),
        ('option', 'Что защищает журнал предзаписи?', 'Временные таблицы', 'Временные таблицы сеанса', 'Нет. Данные временных таблиц не журналируются.', NULL),
        ('option', 'Что защищает журнал предзаписи?', 'Страницы данных журналируемых таблиц и их индексов', 'Страницы журналируемых таблиц и индексов', 'Изменения данных журналируемых таблиц и индексов защищаются WAL.', NULL),
        ('option', 'Что верно для контрольной точки?', 'Выполняется только при остановке сервера', 'Выполняется по команде администратора, а не по расписанию', 'Выполняется периодически: по времени и по объёму журнала.', 'Выполняется периодически: по времени и по объёму журнала, а также при остановке сервера и по команде CHECKPOINT.'),
        ('option', 'Что верно для контрольной точки?', 'Сбрасывает на диск все грязные буферы, включая буферы clog', 'Сбрасывает все грязные буферы, включая буферы clog', 'Записываются все буферы, грязные на начало контрольной точки, в том числе служебные.', NULL),
        ('option', 'Что верно для контрольной точки?', 'Удаляет мёртвые версии строк', 'Удаляет мёртвые версии строк из таблиц', 'Это задача очистки.', NULL),
        ('option', 'Что хранит буфер в буферном кеше, кроме самой страницы данных?', 'Сжатую копию соседних страниц', 'Сжатую копию соседних страниц того же файла', 'Буфер содержит одну страницу.', NULL),
        ('option', 'Что хранит буфер в буферном кеше, кроме самой страницы данных?', 'Дополнительную информацию, например имя файла и положение страницы в нём', 'Служебные сведения: файл и номер страницы в нём', 'По ней понятно, какая страница лежит в буфере.', 'По этим сведениям, например имени файла и положению страницы в нём, понятно, какая страница лежит в буфере.'),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Чтобы реплики успели её прочитать', 'Чтобы реплики успели прочитать её из кеша', 'Реплики получают журнальные записи, а не страницы.', NULL),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Страницы пишутся на диск только при остановке сервера', 'Страницы ждут остановки сервера, чтобы записаться разом', 'Их записывают контрольные точки, фоновая запись и вытеснение.', NULL),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Её должна сначала проверить очистка', 'Её должна сначала проверить очистка на мёртвые версии', 'Перед записью страницы на диск никакая проверка очисткой не требуется.', NULL),
        ('option', 'Почему изменённая страница записывается на диск не сразу?', 'Ради производительности: запись асинхронна и может откладываться', 'Ради производительности: запись можно отложить', 'Надёжность при этом обеспечивает журнал.', 'Запись асинхронна и может откладываться, а надёжность при этом обеспечивает журнал.'),
        ('option', 'Процессу нужна страница, которой нет в буферном кеше. Что он делает?', 'Просит ОС прочитать её и помещает в буферный кеш', 'Читает её через ОС в буферный кеш', 'ОС может прочитать страницу с диска или найти её в собственном кеше.', 'Просит ОС прочитать страницу и помещает её в буферный кеш; ОС может прочитать её с диска или найти в собственном кеше.'),
        ('option', 'Процессу нужна страница, которой нет в буферном кеше. Что он делает?', 'Ждёт ближайшей контрольной точки', 'Ждёт ближайшей контрольной точки для чтения', 'Контрольная точка записывает грязные буферы и чтению не нужна.', NULL),
        ('option', 'Процессу нужна страница, которой нет в буферном кеше. Что он делает?', 'Возвращает ошибку', 'Возвращает ошибку «страница не найдена»', 'Отсутствие страницы в кеше — обычная ситуация.', NULL),
        ('option', 'Почему запись через журнал эффективнее, чем запись каждой изменённой страницы сразу на диск?', 'Журнал читается при каждом запросе', 'Журнал читается при каждом запросе к таблице', 'Обычные запросы журнал не читают: таблицы читаются через буферный кеш. Журнал читают при восстановлении после сбоя и при репликации.', NULL),
        ('option', 'Почему запись через журнал эффективнее, чем запись каждой изменённой страницы сразу на диск?', 'Журнал не нужно сбрасывать на диск', 'Журнал не нужно сбрасывать на диск при фиксации', 'Наоборот, записи должны попасть на диск раньше изменённых данных.', NULL),
        ('option', 'Чем рискует асинхронный режим фиксации?', 'Можно потерять несколько последних зафиксированных транзакций, но согласованность после сбоя сохранится', 'Можно потерять последние подтверждённые транзакции', 'Записи журнала пишет фоновый процесс walwriter с небольшой задержкой.', 'Можно потерять несколько последних зафиксированных транзакций, но согласованность после сбоя сохранится: записи журнала пишет фоновый процесс walwriter с небольшой задержкой.'),
        ('option', 'Страница данных сбрасывается на диск, а соответствующая ей журнальная запись ещё не записана. Что произойдёт?', 'Сервер остановится с ошибкой', 'Сервер остановится с ошибкой записи', 'Это штатная ситуация.', NULL),
        ('option', 'Страница данных сбрасывается на диск, а соответствующая ей журнальная запись ещё не записана. Что произойдёт?', 'Журнальная запись будет сразу записана в синхронном режиме', 'Журнальная запись будет сначала сброшена на диск', 'Журнал всегда должен попасть на диск раньше данных.', NULL),
        ('option', 'Какие обычные транзакции после восстановления после сбоя считаются оборванными?', 'Никакие', 'Никакие: восстановление доводит до конца все транзакции', 'Незафиксированные к моменту сбоя транзакции обрываются.', NULL),
        ('option', 'Когда контрольная точка считается выполненной?', 'Когда записаны все буферы, которые были грязными в момент её начала', 'Когда записаны буферы, грязные на момент её начала', 'Тогда на диске гарантированно все изменения, сделанные до начала контрольной точки; более поздние изменения записывать к её завершению не требуется.', NULL),
        ('option', 'Когда контрольная точка считается выполненной?', 'В момент её начала', 'В момент её начала, ещё до записи буферов', 'Сама «точка» — момент начала, но выполненной она считается только после записи.', NULL),
        ('option', 'Когда контрольная точка считается выполненной?', 'Когда журнал скопирован в архив', 'Когда журнал до неё скопирован в архив', 'Архивирование журнала к контрольной точке не относится.', NULL),
        ('option', 'Когда контрольная точка считается выполненной?', 'Когда буферный кеш полностью очищен', 'Когда буферный кеш полностью очищен от страниц', 'Контрольная точка не освобождает буферный кеш: записанные страницы остаются в нём, а параллельные изменения снова делают часть буферов грязными.', NULL),
        ('option', 'Что добавляет в журнал уровень replica по сравнению с minimal?', 'Ничего: это синонимы', 'Ничего: уровни minimal и replica пишут одно и то же', 'На уровне minimal часть изменений в журнал не попадает.', NULL),
        ('option', 'Что добавляет в журнал уровень replica по сравнению с minimal?', 'Информацию для логической репликации', 'Информацию для логической репликации и декодирования', 'Её добавляет уровень logical.', NULL),
        ('option', 'Что добавляет в журнал уровень replica по сравнению с minimal?', 'Информацию, позволяющую делать резервные копии и репликацию', 'Данные для резервных копий и физической репликации', 'На уровне minimal журнал обеспечивает только восстановление после сбоя.', NULL),
        ('option', 'Что добавляет в журнал уровень replica по сравнению с minimal?', 'Тексты выполненных запросов', 'Тексты выполненных запросов для аудита и отладки', 'Журнал содержит изменения данных, а не тексты запросов.', NULL),
        ('option', 'Что делает сервер при остановке в режиме fast?', 'Сразу запускается снова', 'Сразу запускается снова с теми же настройками', 'Это остановка, а не перезапуск.', NULL),
        ('option', 'Что делает сервер при остановке в режиме fast?', 'Обрывает открытые соединения и перед выключением выполняет контрольную точку', 'Обрывает соединения и выполняет контрольную точку', 'Поэтому при следующем запуске сервер сразу готов к работе.', 'Обрывает открытые соединения и перед выключением выполняет контрольную точку, поэтому при следующем запуске сервер сразу готов к работе.'),
        ('option', 'Что произойдёт, если на сервере PostgreSQL установить fsync = off?', 'Журнал предзаписи перестанет записываться', 'Журнал предзаписи перестанет записываться совсем', 'Журнал пишется по-прежнему, только без ожидания записи на диск.', NULL),
        ('option', 'Что произойдёт, если на сервере PostgreSQL установить fsync = off?', 'Сервер перестанет принудительно сбрасывать данные на диск; после сбоя ОС или питания база может быть повреждена безвозвратно', 'После сбоя ОС или питания база может быть повреждена', 'Без сброса нет гарантии, что журнал попал на диск раньше изменённых страниц.', 'Сервер перестанет принудительно сбрасывать данные на диск, и нет гарантии, что журнал попал на диск раньше изменённых страниц: после сбоя ОС или питания база может быть повреждена безвозвратно.'),
        ('option', 'Что произойдёт, если на сервере PostgreSQL установить fsync = off?', 'Будут теряться только последние транзакции, а база останется согласованной', 'Будут теряться последние транзакции, а база останется согласованной', 'Так ведёт себя synchronous_commit = off; при fsync = off возможна порча базы.', NULL),
        ('option', 'К каким файлам относится параметр wal_sync_method?', 'Только к файлам журнала предзаписи; файлы данных на контрольной точке сбрасываются вызовом fsync', 'К файлам журнала предзаписи', 'Название параметра это и говорит: wal — журнал.', 'Только к файлам журнала предзаписи, это видно и по названию. Файлы данных на контрольной точке сбрасываются вызовом fsync.'),
        ('option', 'К каким файлам относится параметр wal_sync_method?', 'Только к файлам данных таблиц и индексов', 'К файлам данных таблиц и индексов', 'Наоборот, только к журналу.', NULL),
        ('option', 'Чем системный вызов fdatasync отличается от fsync?', 'fdatasync может не сбрасывать метаданные, не нужные для чтения данных, например время изменения файла', 'fdatasync может не сбрасывать лишние метаданные файла', 'Поэтому он может быть быстрее fsync; насколько — зависит от файловой системы и диска.', 'Например, время изменения файла, не нужное для чтения данных. Поэтому он может быть быстрее fsync; насколько — зависит от файловой системы и диска.'),
        ('option', 'Чем системный вызов fdatasync отличается от fsync?', 'fdatasync работает только для файлов журнала PostgreSQL', 'fdatasync работает с файлами журнала PostgreSQL, а не данных', 'Это обычный системный вызов Linux, им может пользоваться любая программа.', NULL),
        ('option', 'Чем системный вызов fdatasync отличается от fsync?', 'fdatasync сбрасывает все открытые файлы процесса', 'fdatasync сбрасывает все открытые файлы процесса сразу', 'Оба вызова работают с одним файлом, переданным по номеру.', NULL),
        ('option', 'Чем системный вызов fdatasync отличается от fsync?', 'fdatasync не ждёт записи на диск', 'fdatasync возвращается, не дожидаясь записи на диск', 'Успешный вызов в обоих случаях означает, что данные записаны на устойчивый носитель, если накопитель честно выполняет сброс своего кеша; если вызов вернул -1, гарантии нет.', NULL),
        ('option', 'pg_test_fsync при двух записях по 8 КБ показал: open_datasync — 372 операции в секунду, fdatasync — 1338. Почему open_datasync медленнее?', 'С open_datasync каждая запись сама ждёт сброса на диск, их две; с fdatasync — две записи и один сброс', 'С open_datasync сбросов два, с fdatasync — один', 'Это объясняет выигрыш в таком сценарии; его величина зависит от системы. В Linux значение по умолчанию — fdatasync.', 'С open_datasync каждая запись сама ждёт сброса на диск, их две; с fdatasync — две записи и один сброс. Величина выигрыша зависит от системы; в Linux значение по умолчанию — fdatasync.'),
        ('option', 'pg_test_fsync при двух записях по 8 КБ показал: open_datasync — 372 операции в секунду, fdatasync — 1338. Почему open_datasync медленнее?', 'fdatasync не ждёт записи на диск', 'fdatasync не ждёт записи на диск, отсюда скорость', 'fdatasync ждёт, но вызывается один раз на две записи.', NULL),
        ('option', 'Остальные настройки сохранности оставлены по умолчанию. Что верно при сравнении двух отдельных случаев: synchronous_commit = off (при fsync = on) и fsync = off?', 'Оба параметра одинаково безопасны: теряются только последние транзакции', 'Оба параметра одинаково безопасны: теряются последние транзакции', 'fsync = off рискует целостностью всей базы.', NULL),
        ('option', 'Остальные настройки сохранности оставлены по умолчанию. Что верно при сравнении двух отдельных случаев: synchronous_commit = off (при fsync = on) и fsync = off?', 'При synchronous_commit = off после сбоя ОС можно потерять последние подтверждённые транзакции, но база останется согласованной', 'При synchronous_commit = off возможна потеря последних транзакций', 'Журнал всё равно сбрасывается, только позже, процессом walwriter.', 'После сбоя ОС можно потерять последние подтверждённые транзакции, но база останется согласованной: журнал всё равно сбрасывается, только позже, процессом walwriter.'),
        ('option', 'Остальные настройки сохранности оставлены по умолчанию. Что верно при сравнении двух отдельных случаев: synchronous_commit = off (при fsync = on) и fsync = off?', 'При synchronous_commit = off журнал предзаписи не пишется', 'При synchronous_commit = off журнал предзаписи не пишется на диск', 'Журнал пишется; клиент просто не ждёт его сброса на диск.', 'Журнал пишется и сбрасывается на диск; клиент просто не ждёт этого сброса.'),
        ('option', 'Зачем нужен параметр full_page_writes = on?', 'Первое изменение страницы после контрольной точки записывает в журнал её полную копию, чтобы после сбоя восстановить страницу, недописанную на диск', 'Чтобы восстановить после сбоя частично записанную страницу', 'Атомарность записи целой страницы на диск не гарантируется: при сбое питания может сохраниться лишь её часть.', 'Первое изменение страницы после контрольной точки записывает в журнал её полную копию. Атомарность записи целой страницы не гарантируется: при сбое питания может сохраниться лишь её часть.'),
        ('option', 'Зачем нужен параметр full_page_writes = on?', 'Он нужен только для логической репликации', 'Он нужен для логической репликации и декодирования', 'Этот механизм нужен для восстановления страниц после сбоя.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
